aningVi":"Won Hàn Quốc"},"L/W/H":{"meaningKo":"길이·너비·높이","meaningEn":"Length / Width / Height","meaningVi":"Dài / Rộng / Cao"},"LCL":{"meaningKo":"혼재 화물","meaningEn":"Less Than Container Load","meaningVi":"Hàng Lẻ"},"LWH":{"meaningKo":"길이·너비·높이","meaningEn":"Length, Width And Height","meaningVi":"Dài, Rộng Và Cao"},"M/B/L":{"meaningKo":"마스터 선하증권","meaningEn":"Master Bill Of Lading","meaningVi":"Vận Đơn Chủ"},"M/W/U":{"meaningKo":"","meaningEn":"","meaningVi":""},"MAWB":{"meaningKo":"마스터 항공 화물 운송장","meaningEn":"Master Air Waybill","meaningVi":"Vận Đơn Hàng Không Chủ"},"MBL":{"meaningKo":"마스터 선하증권","meaningEn":"Master Bill Of Lading","meaningVi":"Vận Đơn Chủ"},"NV":{"meaningKo":"","meaningEn":"","meaningVi":""},"NVOCC":{"meaningKo":"무선박 운송인","meaningEn":"Non-Vessel Operating Common Carrier","meaningVi":"Người Vận Chuyển Không Sở Hữu Tàu"},"OOG":{"meaningKo":"규격 초과 화물","meaningEn":"Out-Of-Gauge Cargo","meaningVi":"Hàng Quá Khổ"},"OT":{"meaningKo":"초과 근무","meaningEn":"Overtime","meaningVi":"Làm Thêm Giờ"},"PCS":{"meaningKo":"수량 단위","meaningEn":"Pieces","meaningVi":"Đơn Vị Cái"},"PDF":{"meaningKo":"휴대용 문서 형식","meaningEn":"Portable Document Format","meaningVi":"Định Dạng Tài Liệu Di Động"},"PNG":{"meaningKo":"무손실 이미지 파일 형식","meaningEn":"Portable Network Graphics","meaningVi":"Định Dạng Ảnh Nén Không Mất Dữ Liệu"},"POD":{"meaningKo":"양하항","meaningEn":"Port Of Discharge","meaningVi":"Cảng Dỡ Hàng"},"POL":{"meaningKo":"선적항","meaningEn":"Port Of Loading","meaningVi":"Cảng Xếp Hàng"},"PT":{"meaningKo":"공정 기본 물리 시간","meaningEn":"Basic Physical Process Time","meaningVi":"Thời Gian Vật Lý Cơ Bản Của Công Đoạn"},"PT/ST":{"meaningKo":"물리 시간·표준 시간","meaningEn":"Physical Time / Standard Time","meaningVi":"Thời Gian Vật Lý / Thời Gian Tiêu Chuẩn"},"QC":{"meaningKo":"품질 관리","meaningEn":"Quality Control","meaningVi":"Kiểm Soát Chất Lượng"},"QR":{"meaningKo":"빠른 응답 코드","meaningEn":"Quick Response Code","meaningVi":"Mã Phản Hồi Nhanh"},"SAAS":{"meaningKo":"서비스형 소프트웨어","meaningEn":"Software As A Service","meaningVi":"Phần Mềm Dưới Dạng Dịch Vụ"},"SEO":{"meaningKo":"검색 엔진 최적화","meaningEn":"Search Engine Optimization","meaningVi":"Tối Ưu Hóa Công Cụ Tìm Kiếm"},"SHPR":{"meaningKo":"송하인","meaningEn":"Shipper","meaningVi":"Người Gửi Hàng"},"SKU":{"meaningKo":"재고 관리 단위","meaningEn":"Stock Keeping Unit","meaningVi":"Đơn Vị Quản Lý Tồn Kho"},"SL":{"meaningKo":"","meaningEn":"","meaningVi":""},"SQL":{"meaningKo":"구조화 질의 언어","meaningEn":"Structured Query Language","meaningVi":"Ngôn Ngữ Truy Vấn Có Cấu Trúc"},"SR":{"meaningKo":"운송 신청","meaningEn":"Shipping Request","meaningVi":"Yêu Cầu Vận Chuyển"},"SSE":{"meaningKo":"서버 변경 이벤트","meaningEn":"Server-Sent Events","meaningVi":"Sự Kiện Do Máy Chủ Gửi"},"ST":{"meaningKo":"계획·생산능력 기준 시간","meaningEn":"Standard Time For Planning And Capacity","meaningVi":"Thời Gian Tiêu Chuẩn Cho Kế Hoạch Và Năng Lực Sản Xuất"},"ST/AT":{"meaningKo":"표준 시간·실제 시간","meaningEn":"Standard Time / Actual Time","meaningVi":"Thời Gian Tiêu Chuẩn / Thời Gian Thực Tế"},"ST/CT":{"meaningKo":"표준 시간·계약 시간","meaningEn":"Standard Time / Contract Time","meaningVi":"Thời Gian Tiêu Chuẩn / Thời Gian Hợp Đồng"},"ST/PT":{"meaningKo":"표준 시간·물리 시간","meaningEn":"Standard Time / Physical Time","meaningVi":"Thời Gian Tiêu Chuẩn / Thời Gian Vật Lý"},"SWIFT":{"meaningKo":"국제은행간금융통신협회","meaningEn":"Society For Worldwide Interbank Financial Telecommunication","meaningVi":"Hiệp Hội Viễn Thông Tài Chính Liên Ngân Hàng Toàn Cầu"},"SX":{"meaningKo":"","meaningEn":"","meaningVi":""},"TBD":{"meaningKo":"미정","meaningEn":"To Be Determined","meaningVi":"Chưa Xác Định"},"TEU":{"meaningKo":"20피트 컨테이너 환산 단위","meaningEn":"Twenty-Foot Equivalent Unit","meaningVi":"Đơn Vị Tương Đương Container 20 Feet"},"TK":{"meaningKo":"","meaningEn":"","meaningVi":""},"UI":{"meaningKo":"사용자 인터페이스","meaningEn":"User Interface","meaningVi":"Giao Diện Người Dùng"},"UN":{"meaningKo":"국제연합","meaningEn":"United Nations","meaningVi":"Liên Hợp Quốc"},"UN/LOCODE":{"meaningKo":"무역·운송 장소 코드","meaningEn":"United Nations Code For Trade And Transport Locations","meaningVi":"Mã Địa Điểm Thương Mại Và Vận Tải Của Liên Hợp Quốc"},"UNECE":{"meaningKo":"유엔 유럽 경제 위원회","meaningEn":"United Nations Economic Commission For Europe","meaningVi":"Ủy Ban Kinh Tế Liên Hợp Quốc Về Châu Âu"},"URL":{"meaningKo":"인터넷 자원 주소","meaningEn":"Uniform Resource Locator","meaningVi":"Địa Chỉ Tài Nguyên Trên Internet"},"USD":{"meaningKo":"미국 달러","meaningEn":"United States Dollar","meaningVi":"Đô La Mỹ"},"VAT":{"meaningKo":"부가가치세","meaningEn":"Value Added Tax","meaningVi":"Thuế Giá Trị Gia Tăng"},"VND":{"meaningKo":"베트남 동","meaningEn":"Vietnamese Dong","meaningVi":"Đồng Việt Nam"},"VND/KRW":{"meaningKo":"베트남 동·대한민국 원","meaningEn":"Vietnamese Dong / South Korean Won","meaningVi":"Đồng Việt Nam / Won Hàn Quốc"},"VP":{"meaningKo":"","meaningEn":"","meaningVi":""},"XLSX":{"meaningKo":"엑셀 파일 형식","meaningEn":"Excel Workbook Format","meaningVi":"Định Dạng Tệp Excel"},"XML":{"meaningKo":"확장 가능 마크업 언어","meaningEn":"Extensible Markup Language","meaningVi":"Ngôn Ngữ Đánh Dấu Mở Rộng"}}$meanings$::jsonb; base jsonb; legacy text; ko text; known boolean;
BEGIN
 base:=defaults->upper(entry->>'acronym'); legacy:=coalesce(entry->>'meaning','');
 known:=base IS NOT NULL AND (legacy='' OR legacy=base->>'meaningKo');
 ko:=coalesce(entry->>'meaningKo',nullif(legacy,''),CASE WHEN known THEN base->>'meaningKo' ELSE '' END);
 RETURN entry||jsonb_build_object('meaning',ko,'meaningKo',ko,
  'meaningEn',coalesce(entry->>'meaningEn',CASE WHEN known THEN base->>'meaningEn' ELSE '' END),
  'meaningVi',coalesce(entry->>'meaningVi',CASE WHEN known THEN base->>'meaningVi' ELSE '' END));
END $$;
DO $$ DECLARE before_value jsonb; after_value jsonb; entries jsonb; BEGIN
 SELECT value INTO before_value FROM "SystemSetting" WHERE key='TEXT_ACRONYMS:1' FOR UPDATE;
 IF before_value IS NULL OR before_value->>'meaningLanguagesVersion'='1' THEN RETURN; END IF;
 SELECT coalesce(jsonb_agg(baro_text_acronym_meanings_v1(entry) ORDER BY position),'[]'::jsonb) INTO entries
 FROM jsonb_array_elements(before_value->'entries') WITH ORDINALITY AS source(entry,position);
 after_value:=before_value||jsonb_build_object('revision',coalesce((before_value->>'revision')::integer,0)+1,'meaningLanguagesVersion',1,'entries',entries);
 INSERT INTO "SystemSetting"(key,value,"updatedAt") VALUES('TEXT_ACRONYMS_AUDIT:meanings-v1',
 jsonb_build_object('baseRevision',coalesce((before_value->>'revision')::integer,0),'actor','migration:20261127030000_text_acronym_meanings','before',before_value,'after',after_value),CURRENT_TIMESTAMP);
 UPDATE "SystemSetting" SET value=after_value,"updatedAt"=CURRENT_TIMESTAMP WHERE key='TEXT_ACRONYMS:1';
END $$;
